function createEnv(sdk) {
  var LIMIT = 1800;
  var PADDLE_Y = 450;
  var PADDLE_W = 112;
  var BALL_R = 10;
  var CATCH_Y = PADDLE_Y - 9 - BALL_R;
  var rng, bx, by, vx, vy, px, steps, done;
  var terms = [0, 0, 0, 0];
  var obs = [0, 0, 0, 0, 0, 0, 0];

  function resetTerms() {
    for (var i = 0; i < terms.length; i++) terms[i] = 0;
  }

  return {
    reset: function (seed) {
      rng = sdk.rng(seed);
      bx = 400 + rng.range(-110, 110);
      by = 285;
      vx = rng.range(-1.2, 1.2);
      vy = 0;
      px = 400;
      steps = 0;
      done = false;
      resetTerms();
    },

    step: function (action) {
      if (done) return;

      var move = action === 0 ? -1 : (action === 2 ? 1 : 0);
      px = sdk.clamp(px + move * 6.5, PADDLE_W / 2, 800 - PADDLE_W / 2);
      if (move !== 0) terms[3] += 1 / LIMIT;

      var oldY = by;
      vx = sdk.clamp(vx, -5.5, 5.5);
      vy += 0.24;
      bx += vx;
      by += vy;

      if (bx < BALL_R) {
        bx = BALL_R;
        vx = Math.abs(vx);
      } else if (bx > 800 - BALL_R) {
        bx = 800 - BALL_R;
        vx = -Math.abs(vx);
      }

      if (vy > 0 && oldY <= CATCH_Y && by >= CATCH_Y &&
          Math.abs(bx - px) <= PADDLE_W / 2 + BALL_R) {
        by = CATCH_Y;
        var offset = sdk.clamp((bx - px) / (PADDLE_W / 2), -1, 1);
        vx = sdk.clamp(vx + offset * 2.8, -5.5, 5.5);
        vy = -8.5 + Math.abs(offset) * 0.4;
        terms[1] += 1;
      }

      var height = sdk.clamp((CATCH_Y - by) / 270, 0, 1);
      terms[0] += height / LIMIT;

      steps += 1;
      if (by > 490) {
        terms[2] += 1;
        done = true;
      }
      if (steps >= LIMIT) done = true;
    },

    observe: function () {
      obs[0] = sdk.clamp((bx - 400) / 400, -1, 1);
      obs[1] = sdk.clamp((250 - by) / 250, -1, 1);
      obs[2] = sdk.clamp(vx / 6, -1, 1);
      obs[3] = sdk.clamp(vy / 10, -1, 1);
      obs[4] = sdk.clamp((px - 400) / 400, -1, 1);
      obs[5] = sdk.clamp((bx - px) / 400, -1, 1);
      obs[6] = vy > 0 ? 1 : -1;
      return obs;
    },

    get done() {
      return done;
    },

    terms: terms,

    render: function (draw, ghost) {
      if (!ghost) {
        draw.clear(sdk.colors.bg);
        draw.line(0, PADDLE_Y + 12, 800, PADDLE_Y + 12, sdk.colors.dim, 2);
        draw.text("Bounces: " + terms[1], 24, 32, sdk.colors.fg, 18);
      }
      draw.rect(px - PADDLE_W / 2, PADDLE_Y - 9, PADDLE_W, 18, sdk.colors.accent);
      if (!ghost) {
        draw.circle(bx, by, BALL_R, sdk.colors.good);
      }
    },

    humanAct: function (input) {
      if (input.held.has("ArrowLeft")) return 0;
      if (input.held.has("ArrowRight")) return 2;
      return 1;
    }
  };
}
